      if (!m) throw new Error(`car\xE1cter no admitido \xAB${c}\xBB`);
      const w = m[0].toUpperCase();
      out.push(w === "AND" ? "Y" : w === "OR" ? "O" : w === "NOT" ? "NO" : w);
