    cadena("Arranque de K1 (Rearme supervisado)", [["SB7", o.rearme], ["KM1 nc", !P2.km1], ["KM2 nc", !P2.km2], ["SB6 nc", !o.marcha]], "INF/S", pot && !P2.discrepancia);
    cadena("Bobina de KM2 (tres hilos)", [["K1 13-14", P2.k1], ["SB8 nc", !o.paroInm], ["F1 95-96", !f.termico], ["SB6\u2225KM2", o.marcha || P2.km2]], "KM2", pot);
    cadena("Bobina de KM1", [["%Q0.3", !!(P2.Q[0] & 8)], ["K1 23-24", P2.k1], [f.km1Abierta ? "bobina \u2717" : "bobina", !f.km1Abierta]], "KM1", pot);
