    $("#txtK1").textContent = `K1: ${P2.motivoK1}.` + (P2.bajoNivel.some(Boolean) ? ` Silo ${P2.bajoNivel.map((x, i) => x ? i + 1 : 0).filter(Boolean).join(", ")} por debajo del nivel m\xEDnimo: fuera de la validez declarada.` : "") + (P2.carroRebasado() ? " El carro rebasa su capacidad." : "") + (P2.derrame > 0.01 ? ` Producto fuera del carro: ${fmt(P2.derrame, 1)} kg.` : "");
    const lista = [];
    for (let i = 0; i < 8; i++) if (al & 1 << i) lista.push(`AL${i + 1} ${NOMBRE_AL[i]}`);
    const tAl = lista.length ? "Alarmas: " + lista.join("; ") + "." : "Sin alarmas.";
    if ($("#txtAlarmas").textContent !== tAl) $("#txtAlarmas").textContent = tAl;
    const nota = !P2.alimentado ? "Tablero sin alimentaci\xF3n." : E.plcStop ? E.val.errores.length ? "PLC parado (STOP): tu programa tiene errores; corr\xEDgelos en la fase C." : "PLC parado (STOP): arranca cuando registres tu c\xE1lculo previo en la fase B." : `Programa transferido: ${E.prog.redes.length} pelda\xF1os.` + (b.fuerzas.size ? ` Entradas forzadas: ${b.fuerzas.size}.` : "");
